<?php use App\Support\App;App::requireAdmin();$rows=App::db()->query('SELECT d.*,u.name,u.email FROM deposits d JOIN users u ON u.id=d.user_id ORDER BY d.id DESC LIMIT 300')->fetchAll();$title='Deposits';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div><h1 class="page-title">Deposits</h1><p class="page-sub">Monitor request deposit dan settlement gateway.</p></div><div class="saas-card mt-6 overflow-auto"><table class="w-full text-sm min-w-[800px]"><thead><tr><th>Deposit</th><th>User</th><th>Gateway</th><th>Amount</th><th>Status</th><th>Reference</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t" style="border-color:var(--line)"><td class="font-semibold"><?=htmlspecialchars($r['deposit_number'])?></td><td><?=htmlspecialchars($r['name'])?><div class="text-xs text-zinc-500"><?=htmlspecialchars($r['email'])?></div></td><td><span class="badge"><?=htmlspecialchars($r['gateway'])?></span></td><td>Rp<?=number_format($r['amount'],0,',','.')?></td><td><span class="badge"><?=htmlspecialchars($r['status'])?></span></td><td><?=htmlspecialchars($r['provider_reference']??'-')?></td><td><?=htmlspecialchars($r['created_at'])?></td></tr><?php endforeach?></tbody></table></div><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>